<script setup lang="ts">import { MasonryItem,MasonryRoot,MasonryViewport } from '@fex-design/vue/primitive/masonry';import Button from '@fex-design/vue/ui/button';import { ref } from 'vue';import { masonryItems } from './data';const summaries=['待确认需求范围','正在整理交互状态','已完成视觉走查','等待接口数据','正在补充异常分支','已进入回归验证','准备发布说明','等待最终确认'],details=['补充响应式宽度变化后的验收结果。','记录图片加载完成后的重新测量过程。','确认动态内容不会覆盖相邻项目。'],items=masonryItems.slice(0,8),target=ref(0),detailCount=ref(0);const switchTarget=()=>{target.value=(target.value+1)%items.length;detailCount.value=0}</script>
<template><div class="grid gap-space-md"><div class="flex flex-wrap items-center gap-space-sm rounded-md border border-border bg-muted-background p-space-sm"><span class="mr-auto text-sm">当前观察：<strong>Card {{target+1}}</strong> · 新增 {{detailCount}} 段</span><Button size="sm" variant="outline" @click="switchTarget">切换目标</Button><Button size="sm" @click="detailCount=Math.min(details.length,detailCount+1)">追加内容</Button><Button size="sm" variant="outline" :disabled="!detailCount" @click="detailCount=Math.max(0,detailCount-1)">收起内容</Button><Button size="sm" variant="outline" @click="detailCount=details.length">连续更新</Button><Button size="sm" variant="ghost" @click="detailCount=0">重置</Button></div><MasonryRoot :columns="{minColumnWidth:220,max:4}" :gap="16"><MasonryViewport><MasonryItem v-for="(item,index) in items" :key="item.id" :item-key="item.id" :index="index"><article class="grid gap-space-sm rounded-md border p-space-md" :class="index===target?'border-primary bg-primary/5':'border-border bg-background'"><div class="flex items-center justify-between gap-space-sm"><strong>{{item.title}}</strong><span class="rounded-full bg-muted px-2 py-0.5 text-xs text-muted-foreground">{{index===target?'观察中':`第 ${index+1} 项`}}</span></div><p class="text-sm text-muted-foreground">{{summaries[index]}}</p><template v-if="index===target"><p v-for="detail in details.slice(0,detailCount)" :key="detail" class="border-t border-border pt-space-sm text-sm">{{detail}}</p></template></article></MasonryItem></MasonryViewport></MasonryRoot></div></template>
